void solve() {
  int n, m;
  long long k;
  cin >> n >> m >> k;
  vector<vector<int>> ev(m);
  for (int i = 0; i < m; ++i) {
    int x; cin >> x;
    ev[x - 1].push_back(-1);
  }
  for (int i = 0; i < n; ++i) {
    int x, y, z;
    cin >> x >> y >> z;
    ev[x - 1].push_back(z - y);
    k -= y;
  }
  int ans = 0;
  multiset<int> s;
  for (int i = 0; i < m; ++i) {
    reverse(ev[i].begin(), ev[i].end());
    for (int x : ev[i]) {
      if (x == -1) {
        if (!s.empty()) {
          s.erase(--s.end());
          ++ans;
        }
      } else {
        s.insert(x);
      }
    }
  }
  while (!s.empty() && *s.begin() <= k) {
    k -= *s.begin();
    s.erase(s.begin());
    ++ans;
  }
  cout << ans << '\n';
}

