#include<bits/stdc++.h>

using namespace std;

const int MOD = 998244353;
const int LOGN = 61;

int add(int x, int y)
{
    x += y;
    if(x >= MOD) x -= MOD;
    if(x < 0) x += MOD;
    return x;
}

int sub(int x, int y)
{
    return add(x, -y);
}

int mul(int x, int y)
{
    return (x * 1ll * y) % MOD;
}   

int binpow(int x, int y)
{
    int z = 1;
    while(y > 0)
    {
        if(y % 2 == 1) z = mul(z, x);
        x = mul(x, x);
        y /= 2;
    }
    return z;
}                   

vector<int> get_required(long long x)
{
    vector<int> ans(LOGN);
    int cnt = 0;
    for(int i = LOGN - 1; i >= 0; i--)
    {
        if((x >> i) & 1)
        {
            ans[i + cnt]++;
            cnt++;
        }
    }
    return ans;
}

void solve()
{
    int n, m;
    cin >> n >> m;        
    vector<int> freq(LOGN);
    for(int i = 0; i < n; i++)
    {
        int x;
        cin >> x;
        freq[x]++;
    }

    int max_n = n + m + 111;

    vector<int> fact(max_n, 1);
    for(int i = 1; i < max_n; i++)
        fact[i] = mul(fact[i - 1], i);
    vector<int> inv_fact(max_n);
    for(int i = 0; i < max_n; i++)
        inv_fact[i] = binpow(fact[i], MOD - 2);
    vector<int> pow2(max_n, 1);
    for(int i = 1; i < max_n; i++)
        pow2[i] = mul(pow2[i - 1], 2);

    auto choose = [&](int x, int y)
    {           
        if(x < y || x < 0 || y < 0) return 0;
        return mul(fact[x], mul(inv_fact[y], inv_fact[x - y]));
    };

    auto sum_greater = [&](int x, int y)
    {
        if(y >= x) return 0;
        int ans = pow2[x];
        for(int i = 0; i <= y; i++)
            ans = sub(ans, choose(x, i));
        return ans;
    };

    for(int i = 0; i < m; i++)
    {
        int t;
        long long x;
        cin >> t >> x;
        if(t == 1)
            freq[x]++;
        else if(t == 2)
            freq[x]--;
        else
        {
            auto req = get_required(x);
            int ans = 0;
            int cur = 1;
            int cnt_less = 0;
            for(int i = 0; i < LOGN; i++) cnt_less += freq[i];
            for(int i = LOGN - 1; i >= 0; i--)
            {
                cnt_less -= freq[i];
                ans = add(ans, mul(cur, mul(sum_greater(freq[i], req[i]), pow2[cnt_less])));
                cur = mul(cur, choose(freq[i], req[i]));
            }
            ans = add(ans, cur);
            cout << ans << "\n";
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);    
    int t = 1;
    //cin >> t;
    for(int i = 0; i < t; i++) solve();
}

